fde-v1-m03-tenant-tool-wrapper.alternative:
const callTool = (session, request, store) => {
 if (request.tool !== 'orders.read') return {ok:false,reason:'unknown_tool'};
 let grant;
 for (const one of session.grants) {
  if (one.scope === request.tool && one.tenantId === session.tenantId) { grant=one; break; }
 }
 if (!grant) return {ok:false,reason:'no_grant'};
 const at=Date.parse(session.at);
 if (grant.revokedAt !== null && Date.parse(grant.revokedAt)<=at) return {ok:false,reason:'grant_revoked'};
 if (Date.parse(grant.expiresAt)<=at) return {ok:false,reason:'grant_expired'};
 const status=request.arguments ? request.arguments.status : undefined;
 const records=[];
 for(const row of store.queryOrders(session.tenantId,{status})) records.push({id:row.id,tenantId:row.tenantId,status:row.status,total:row.total});
 return {ok:true,records};
};
